const BISMIL_INFO={id:"ram-prasad-bismil",name:"Ram Prasad Bismil",title:"Revolutionary Martyr, Co-Founder of HRA & Patriotic Poet",lifespan:"11 June 1897 – 19 December 1927",birthplace:"Shahjahanpur, North-Western Provinces (present-day Uttar Pradesh)",martyrdomPlace:"Gorakhpur District Jail (Hanged on 19 December 1927 at age 30)",penNames:"Bismil ('Wounded/Restless'), Ram, Agyat ('Unknown')",organization:"Hindustan Republican Association (HRA), Matrivedi",comrades:"Ashfaqulla Khan, Chandrashekhar Azad, Rajendra Lahiri, Roshan Singh, Sachindra Nath Sanyal",quickStats:[{label:"Martyrdom",value:"19 December 1927",icon:"🇮🇳"},{label:"Kakori Action",value:"9 August 1925",icon:"🚂"},{label:"Organization",value:"HRA Co-Founder",icon:"✊"},{label:"Immortal Poem",value:"Sarfaroshi Ki Tamanna",icon:"📜"},{label:"Autobiography",value:"Atmakatha (Gorakhpur Jail)",icon:"📖"},{label:"Age at Martyrdom",value:"30 Years",icon:"🕊️"}]},BIOGRAPHY_DATA={title:"Biography & Revolutionary Journey",subtitle:"From Shahjahanpur scholar to the immortal leader of the Hindustan Republican Association.",paragraphs:["Ram Prasad Bismil was born on 11 June 1897 in Shahjahanpur, Uttar Pradesh to Muralidhar and Moolmati. Deeply influenced by Swami Dayananda Saraswati's 'Satyarth Prakash' and the Arya Samaj movement, Bismil developed an early passion for Hindi literature, poetry, and social reform. The martyrdom of Ghadar party leaders and Bhai Parmanand's arrest ignited his revolutionary zeal, leading him to found the secret society 'Matrivedi' in 1915.","In 1918, Bismil organized the Mainpuri Conspiracy, publishing banned patriotic literature like 'Desh Vasiyon Ke Naam Sandesh'. When British authorities launched raids, Bismil escaped arrest by living underground in the Yamuna riverbank forests for over two years, working disguised as a farmer while continuing to write revolutionary poems.","In 1924, along with Sachindra Nath Sanyal and Jogesh Chandra Chatterjee, Bismil co-founded the Hindustan Republican Association (HRA) at Kanpur. As the leader of HRA's military wing, Bismil sought to establish a democratic Federal Republic of the United States of India through armed struggle against British colonial rule.","On 9 August 1925, Bismil executed the legendary Kakori Train Action, seizing colonial treasury funds near Lucknow. Arrested shortly after, Bismil faced the famous Kakori Trial. While on death row at Gorakhpur Jail, he penned his immortal autobiography 'Atmakatha' before walking courageously to the gallows on 19 December 1927, chanting 'Vande Mataram'."]},TIMELINE_DATA=[{year:"1897",title:"Born in Shahjahanpur",description:"Ram Prasad Bismil was born on 11 June 1897 to Muralidhar and Moolmati in Shahjahanpur, UP."},{year:"1915",title:"Joins Arya Samaj & Forms Matrivedi",description:"Stirred by revolutionary ideals, he joined the Arya Samaj and established the secret youth organization Matrivedi."},{year:"1918",title:"Mainpuri Conspiracy & Going Underground",description:"Organized the Mainpuri Conspiracy; escaped British arrest by hiding in Yamuna riverbank forests for 2 years."},{year:"1920",title:"Attends Nagpur Congress & Meets Gandhi",description:"Attended the 1920 Nagpur Session of the Indian National Congress, advocating for total independence."},{year:"1924",title:"Co-founding the HRA at Kanpur",description:"Co-founded the Hindustan Republican Association (HRA) with Sachindra Nath Sanyal, drafting its revolutionary constitution."},{year:"1925",title:"Kakori Train Action (9 August)",description:"Led the historic train action at Kakori near Lucknow to secure colonial funds for purchasing arms."},{year:"1925",title:"Arrest & Kakori Trial (26 September)",description:"Arrested by British police in Shahjahanpur; tried during the 18-month Kakori Trial in Lucknow."},{year:"1927",title:"Writing Atmakatha in Prison",description:"Penned his autobiography 'Atmakatha' in Gorakhpur Death Cell, smuggled out by comrade Shiv Verma."},{year:"1927",title:"Martyrdom at Gorakhpur Jail (19 December)",description:"Hanged at Gorakhpur District Jail at age 30, sacrificing his life for India's liberation."}],KAKORI_MOVEMENT_DATA={title:"The Kakori Train Action (9 August 1925)",subtitle:"A daring strike against British colonial treasury near Lucknow.",overview:"On the evening of 9 August 1925, ten brave HRA revolutionaries led by Ram Prasad Bismil stopped the 8-Down passenger train carrying British government tax collections near Kakori railway station, 14 km from Lucknow.",revolutionaries:[{name:"Ram Prasad Bismil",role:"Leader & Operations Commander",status:"Martyred (Hanged 19 Dec 1927)"},{name:"Ashfaqulla Khan",role:"Key Strategist & Armory Specialist",status:"Martyred (Hanged 19 Dec 1927)"},{name:"Chandrashekhar Azad",role:"Rear Guard & Tactical Security",status:"Escaped (Later Martyred 1931)"},{name:"Rajendra Lahiri",role:"Action Strategist",status:"Martyred (Hanged 17 Dec 1927)"},{name:"Roshan Singh",role:"Revolutionary Comrade",status:"Martyred (Hanged 19 Dec 1927)"},{name:"Sachindra Bakshi",role:"HRA Field Commander",status:"Sentenced to Kala Pani (Andaman)"}],significance:["Strict Code of Ethics: The HRA revolutionaries took special care not to rob or harm poor Indian passengers, targeting strictly colonial state treasury funds.","Financing the Struggle: The seized funds were utilized to procure arms from abroad and print anti-colonial propaganda literature.","Catalyst for Youth: The Kakori Trial galvanized millions of Indian youth, directly inspiring Bhagat Singh, Sukhdev, and Rajguru to rename HRA into HSRA (Hindustan Socialist Republican Association)."]},POETRY_DATA=[{id:"sarfaroshi-ki-tamanna",title:"Sarfaroshi Ki Tamanna",language:"Urdu / Hindi",verses:"सरफ़रोशी की तमन्ना अब हमारे दिल में है।\nदेखना है ज़ोर कितना बाज़ू-ए-क़ातिल में है॥\n\nकरता नहीं क्यों दूसरा कुछ बातचीत,\nदेखता हूँ मैं जिसे वो चुप बैठा हुआ है।\nऐ शहीदों की ज़मीं, क्या तू भी ख़ामोश है?\nक्या ख़ामोशी ही तेरी किस्मत का लिखा है॥",translation:"The desire for sacrifice is now in our hearts. Let us see how much strength lies in the executioner's arm...",description:"Originally penned by Bismil Azimabadi and popularized by Ram Prasad Bismil, this poem became the immortal anthem of India's revolutionary freedom fighters."},{id:"rang-de-basanti",title:"Mera Rang De Basanti Chola",language:"Hindi / Braj",verses:"मेरा रंग दे बसंती चोला, माई रंग दे बसंती चोला।\nइसी रंग में रंग के शिवा ने माँ का बंधन खोला,\nइसी रंग में तैर के राणा प्रताप ने देश को बोला।\nमेरा रंग दे बसंती चोला...",translation:"O Mother, dye my robe in the saffron color of sacrifice! In this color Shivaji broke the shackles of the motherland...",description:"Composed in jail prior to execution, celebrating saffron (Basanti) as the color of supreme sacrifice and patriotism."},{id:"atmakatha-excerpt",title:"Autobiography (Atmakatha) Jail Excerpt",language:"Hindi Prose",verses:"यदि देश की सेवा करने में मुझे सहस्रों बार भी जन्म लेना पड़े, तो भी मैं सहर्ष तैयार हूँ।\nमालिक तेरी रज़ा रहे और तू ही तू रहे, \nबाक़ी न मैं रहूँ न मेरी आरज़ू रहे।",translation:"If I have to be born a thousand times to serve my country, I am ready with joy. Let only Thy will prevail, O Master...",description:"Written in Gorakhpur Death Cell days before hanging, reflecting his serene spirituality and unshakeable resolve."}],GALLERY_DATA=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Ram_Prasad_Bismil.jpg/800px-Ram_Prasad_Bismil.jpg",caption:"Historic portrait of Pandit Ram Prasad Bismil, leader of the Hindustan Republican Association.",category:"Portraits"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Ashfaqulla_Khan_and_Ram_Prasad_Bismil.jpg/800px-Ashfaqulla_Khan_and_Ram_Prasad_Bismil.jpg",caption:"Revolutionary comrades Ram Prasad Bismil and Ashfaqulla Khan — symbols of Hindu-Muslim unity.",category:"Revolutionary Comrades"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Kakori_Memorial_UP.jpg/800px-Kakori_Memorial_UP.jpg",caption:"Kakori Shaheed Smarak monument near Lucknow commemorating the 1925 Kakori Train Action.",category:"Memorials & Heritage"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Gorakhpur_Jail_Bismil_Memorial.jpg/800px-Gorakhpur_Jail_Bismil_Memorial.jpg",caption:"The Bismil Martyrdom Memorial inside Gorakhpur District Jail where he was executed on 19 Dec 1927.",category:"Memorials & Heritage"}],REFERENCES_DATA=[{title:"Ram Prasad Bismil Ki Atmakatha",type:"Autobiography",description:"Authentic prison autobiography written by Bismil in Gorakhpur Death Cell, published by National Book Trust (NBT) & Rajkamal Prakashan."},{title:"Kakori Ke Sheheed (NCERT Archive)",type:"Historical Documentation",description:"Official NCERT & Publications Division account detailing the Kakori Train Action trial, martyrs, and court records."},{title:"Hindustan Republican Association Manifesto (1925)",type:"Revolutionary Manifesto",description:"Drafted by Ram Prasad Bismil & Sachindra Nath Sanyal outlining the vision for an independent federal democratic republic."},{title:"Shahjahanpur & Gorakhpur Shaheed Smarak",type:"National Heritage Sites",description:"State archives and martyrdom memorials preserved by the Government of Uttar Pradesh."}];"undefined"!=typeof module&&module.exports&&(module.exports={BISMIL_INFO:BISMIL_INFO,BIOGRAPHY_DATA:BIOGRAPHY_DATA,TIMELINE_DATA:TIMELINE_DATA,KAKORI_MOVEMENT_DATA:KAKORI_MOVEMENT_DATA,POETRY_DATA:POETRY_DATA,GALLERY_DATA:GALLERY_DATA,REFERENCES_DATA:REFERENCES_DATA});